// fillRoutePath substitutes mux path placeholders with safe sample values.
func fillRoutePath(path string) string {
	repl := []struct{ from, to string }{
		{"{filename}", "example.conf"},
		{"{version}", "8.4"},
		{"{domain}", "example.com"},
		{"{id}", "1"},
		{"{name}", "testdb"},
		{"{engine}", "postgresql"},
		{"{email}", "user@example.com"},
		{"{selector}", "default"},
		{"{number}", "1"},
		{"{key}", "memory_limit"},
		{"{zoneId}", "zone123"},
		{"{recordId}", "rec123"},
		{"{targetId}", "target1"},
		{"{jail}", "sshd"},
		{"{ip}", "203.0.113.1"},
		{"{action}", "restart"},
		{"{slug}", "main"},
		{"{pattern}", "spam.example"},
		{"{device}", "sda"},
	}
	for _, r := range repl {
		path = strings.ReplaceAll(path, r.from, r.to)
	}
	return path
}
